import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        StringTokenizer st = new StringTokenizer(br.readLine());
        Map<String, Integer> freq = new HashMap<>();
        for (int i = 0; i < n; i++) freq.merge(st.nextToken(), 1, Integer::sum);
        List<Map.Entry<String, Integer>> es = new ArrayList<>(freq.entrySet());
        es.sort((a, b) -> a.getValue().equals(b.getValue()) ? a.getKey().compareTo(b.getKey()) : b.getValue() - a.getValue());
        for (Map.Entry<String, Integer> e : es) System.out.println(e.getKey() + " " + e.getValue());
    }
}

